const crypto = require('crypto');
const body = $json.body || $json;
const binary = $binary && $binary.data;

const ALLOWED_MIME = {
  'application/pdf': 'PDF',
  'image/jpeg': 'MEDIA',
  'image/jpg': 'MEDIA',
  'image/png': 'MEDIA'
};

if (!binary || !binary.data) {
  throw new Error('No file uploaded (expected multipart field "data")');
}

const mimeType = binary.mimeType;
const sourceDocumentType = ALLOWED_MIME[mimeType];
if (!sourceDocumentType) {
  throw new Error('Unsupported file type: ' + mimeType + '. Allowed: PDF, JPG, JPEG, PNG.');
}

if (!body.knowledge_source_id) {
  throw new Error('knowledge_source_id is required');
}
if (!body.source_document_id) {
  throw new Error('source_document_id is required');
}
if (!body.document_field_extraction_id) {
  throw new Error('document_field_extraction_id is required');
}

const buffer = Buffer.from(binary.data, 'base64');
const fileHash = crypto.createHash('sha256').update(buffer).digest('hex');

return [
  {
    json: {
      knowledge_source_id: body.knowledge_source_id,
      source_document_id: body.source_document_id,
      document_field_extraction_id: body.document_field_extraction_id,
      source_document_type: sourceDocumentType,
      mime_type: mimeType,
      source_type: body.source_type || (sourceDocumentType === 'MEDIA' ? 'PHOTO' : 'DATASHEET'),
      original_file_name: binary.fileName || null,
      customer: body.customer || null,
      site: body.site || null,
      unit: body.unit || null,
      uploaded_by: body.uploaded_by || null,
      file_hash: fileHash,
      file_size: buffer.length
    },
    binary: { data: binary }
  }
];

