const fs = require('fs');
const os = require('os');
const path = require('path');
const input = $('Validate Upload Input').first();
const binary = input.binary.data;
const buffer = Buffer.from(binary.data, 'base64');

// Temporary file only -- discarded at the end of this execution. This is NOT
// a repository storage convention; per Chief Architect ruling, original-file
// persistence is deferred to a future Platform Storage MWO.
const ext = input.json.source_document_type === 'PDF' ? '.pdf' : path.extname(binary.fileName || '') || '.bin';
const tempPath = path.join(os.tmpdir(), `ltsa-doc-upload-${input.json.document_field_extraction_id}${ext}`);
fs.writeFileSync(tempPath, buffer);

return [{ json: { ...input.json, temp_file_path: tempPath } }];

const fs = require('fs');
const prior = $('Write Temp File').first().json;

try {
  fs.unlinkSync(prior.temp_file_path);
} catch (e) {
  // best-effort cleanup of the temporary file; not fatal
}

const stdout = $json.stdout || '';
let extraction;
try {
  extraction = JSON.parse(stdout);
} catch (e) {
  throw new Error('AI Extraction Capability did not return valid JSON: ' + stdout);
}

return [{
  json: {
    document_field_extraction_id: prior.document_field_extraction_id,
    source_document_id: prior.source_document_id,
    source_document_type: prior.source_document_type,
    detected_document_type: extraction.document_type,
    detected_document_type_confidence: extraction.document_type_confidence,
    extraction_provider: extraction.provider || 'claude',
    ocr_text: extraction.ocr_text || '',
    extracted_fields: JSON.stringify(extraction.fields || {})
  }
}];
